import { esc, formatDate, num } from './utils.js';

const regions=['eu-central-1','eu-west-1','eu-west-2','eu-west-3','eu-north-1','eu-central-2','eu-south-1','eu-south-2','us-east-1','us-east-2','us-west-1','us-west-2','ap-southeast-1','ap-southeast-2','ap-northeast-1'];
const regionOptions=(sel='eu-central-1')=>regions.map(r=>`<option ${r===sel?'selected':''}>${r}</option>`).join('');
const budgetOptions=(sel='medium')=>['low','medium','high'].map(x=>`<option value="${x}" ${x===sel?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('');
const pill=(value,kind=value)=>`<span class="pill ${esc(kind)}">${esc(value)}</span>`;

export function landing(settings){
  return `<main class="landing"><div class="landing-grid"><section class="hero">
    <div class="brand big"><span class="logo">☁</span><span>AWS Friendly Counsellor</span></div>
    <h1>Design AWS with confidence,<br><span>without starting as a cloud architect.</span></h1>
    <p class="lead">Guided architecture, cost ranges, service rationale, implementation steps, immutable project history, audit and Terraform baselines — in one web application.</p>
    <div class="hero-actions">${settings.authMode==='cognito'?'<button class="btn primary" data-action="login">Sign in with Cognito</button>':'<a class="btn primary" href="#/dashboard">Open application</a>'}<a class="btn ghost" href="#/settings">Connection settings</a></div>
    <div class="trust-row"><span>✓ No secrets in GitHub Pages</span><span>✓ No backend required</span><span>✓ Data stays in your browser</span><span>✓ AWS connector is optional</span></div>
  </section><aside class="hero-card"><div class="terminal-head"><span></span><span></span><span></span></div><div class="mock-card">
    <div class="eyebrow">Architecture result</div><h3>Serverless customer portal</h3>
    <div class="flow"><span>CloudFront</span><b>→</b><span>API Gateway</span><b>→</b><span>Lambda</span><b>→</b><span>DynamoDB</span></div>
    <div class="metric-grid"><div><strong>$84–$214</strong><small>monthly range</small></div><div><strong>8</strong><small>AWS services</small></div><div><strong>High</strong><small>resilience target</small></div></div>
    <div class="status good">Security baseline included</div></div></aside></div></main>`;
}

export function shell({route,settings,identity,body,health}){
  const nav=[['/dashboard','⌂','Dashboard'],['/advisor','✦','Friendly Advisor'],['/projects','▦','Projects'],['/discovery','◎','AWS Discovery'],['/finops','◫','FinOps'],['/team','♟','Team'],['/audit','≡','Audit'],['/privacy','⌁','Privacy'],['/data','⇩','Data & Backup'],['/settings','⚙','Settings']];
  const links=nav.map(([p,i,l])=>`<a href="#${p}" class="${route===p||route.startsWith(p+'/')?'active':''}"><span>${i}</span>${l}</a>`).join('');
  return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><span class="logo">☁</span><span>AWS Friendly<br><strong>Counsellor</strong></span></a><nav>${links}</nav><div class="side-bottom"><div class="mode-card"><span class="dot ${esc(settings.authMode)}"></span><div><strong>${esc(settings.authMode.toUpperCase())}</strong><small>${settings.authMode==='standalone'?'Local-first · no backend':settings.authMode==='demo'?'Browser simulation':esc(settings.apiBaseUrl||'API not configured')}</small></div></div><a href="#/about" class="tiny-link">Release & limits</a></div></aside><section class="workspace"><header class="topbar"><button class="mobile-menu" data-action="toggle-menu" aria-label="Menu">☰</button><div><strong>${identity?.username?esc(identity.username):'AWS Friendly Counsellor'}</strong><small>${identity?.subject?esc(identity.subject):'Not connected'}</small></div><div class="top-actions"><span class="health ${health?.status==='healthy'?'ok':'warn'}">${health?.status==='healthy'?'● Ready':'● Runtime unavailable'}</span>${settings.authMode==='standalone'?'<button class="btn mini ghost" data-action="install-app">Install app</button>':''}${settings.authMode==='cognito'?'<button class="btn mini ghost" data-action="logout">Sign out</button>':''}</div></header><main class="content">${body}</main></section></div>`;
}

export function onboarding(settings){
  return `<section class="page narrow"><div class="eyebrow">First run</div><h1>Create or open a workspace</h1><p class="muted">In Standalone mode the workspace is stored locally in this browser. You can export and restore it as a portable backup.</p><div class="two-col"><form class="panel" id="create-tenant-form"><h2>Create workspace</h2><label>Workspace name<input name="name" required minlength="2" maxlength="120" placeholder="Acme Cloud Team"></label><label>Slug <small>optional</small><input name="slug" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="acme-cloud-team"></label><button class="btn primary" type="submit">Create workspace</button></form><form class="panel" id="connect-tenant-form"><h2>Existing workspace</h2><label>Tenant ID<input name="tenantId" required placeholder="tenant_…"></label><button class="btn" type="submit">Connect</button><p class="hint">Standalone mode opens only workspaces present in the local vault; connector modes keep server-side authorization.</p></form></div><div class="form-actions"><a class="btn ghost" href="#/data">Restore a full backup</a></div><p class="hint">Mode: <strong>${esc(settings.authMode)}</strong>. ${settings.authMode==='standalone'?'No network connection is required.':settings.authMode==='demo'?'This creates browser-local demo data.':'Your configured connector API must be reachable and CORS must allow this site origin.'}</p></section>`;
}

function projectRow(p){return `<a class="project-row" href="#/project/${encodeURIComponent(p.id)}"><div><strong>${esc(p.name)}</strong><small>${esc(p.region)} · ${num(p.estimated_users)} users</small></div>${pill(p.status,p.status)}</a>`;}

export function dashboard({tenant,projects=[],projectsHasMore=false,health,identity,latest,gamification=null,backupStatus=null,storageInfo=null,pricingStatus=null}){
  const badgeSection=gamification?.badges?.length?`<section class="panel badge-panel"><div class="panel-head"><div><div class="eyebrow">Progress</div><h2>Earned badges</h2></div><a href="#/finops">Open FinOps</a></div><div class="badge-row">${gamification.badges.map(b=>`<div class="badge earned"><strong>${esc(b.name)}</strong><small>${esc(b.description)}</small></div>`).join('')}</div></section>`:'';
  const backupTone=backupStatus?.critical?'danger':backupStatus?.recommended?'draft':'active';
  const backupText=backupStatus?.last_backup_at?`${backupStatus.age_days} day(s) ago`:'Never exported';
  const freshness=pricingStatus?.freshness_state||'unknown';
  const safety=`<section class="panel"><div class="panel-head"><div><div class="eyebrow">Local data safety</div><h2>Standalone health</h2></div><a href="#/data">Manage data</a></div><div class="facts"><div><dt>Backup</dt><dd>${pill(backupText,backupTone)}</dd></div><div><dt>Storage protection</dt><dd>${storageInfo?.persisted===true?'Persistent':storageInfo?.persisted===false?'Best effort':'Unknown'}</dd></div><div><dt>Pricing snapshot</dt><dd>${pill(freshness,freshness==='fresh'?'active':freshness==='aging'?'draft':'archived')}</dd></div><div><dt>Network required</dt><dd>${health?.network_required===false?'No':'Connector only'}</dd></div></div>${backupStatus?.recommended?'<p class="warning">A portable backup is recommended. Browser storage can be cleared by the user or operating system.</p>':''}</section>`;
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">${tenant?esc(tenant.name):'Workspace'}</div><h1>Good to see you${identity?.username?', '+esc(identity.username.split(' ')[0]):''}.</h1><p class="muted">Describe a workload, review an explainable architecture, estimate cost and keep the project locally.</p></div><a class="btn primary" href="#/advisor">✦ Start guided analysis</a></div><div class="stat-grid"><div class="stat"><small>Projects loaded</small><strong>${projects.length}${projectsHasMore?'+':''}</strong><span>${projects.filter(p=>p.status==='active').length} active in this page</span></div><div class="stat"><small>Runtime</small><strong>${health?.status==='healthy'?'Ready':'Unknown'}</strong><span>${esc(health?.environment||'not checked')}</span></div><div class="stat"><small>Persistence</small><strong>${esc(health?.persistence_backend||'—')}</strong><span>${esc(health?.persistence_status||'')}</span></div><div class="stat"><small>Recent analysis sample</small><strong>${esc(latest?.typical_monthly_cost||'—')}</strong><span>${latest?`v${latest.version} · ${formatDate(latest.created_at)}`:'No history in visible projects'}</span></div></div>${safety}${badgeSection}<div class="dash-grid"><section class="panel"><div class="panel-head"><h2>Projects</h2><a href="#/projects">View all</a></div>${projects.length?`<div class="project-list">${projects.slice(0,5).map(projectRow).join('')}</div>`:'<div class="empty"><div class="empty-icon">▦</div><h3>No projects yet</h3><p>Create one or use the Friendly Advisor first.</p><a class="btn" href="#/advisor">Start with Advisor</a></div>'}</section><section class="panel"><h2>Recommended first run</h2><ol class="steps"><li><span>1</span><div><strong>Describe the workload</strong><small>Include users, data, latency, availability and compliance signals.</small></div></li><li><span>2</span><div><strong>Review risks and pillars</strong><small>Every recommendation is tied to explainable workload signals.</small></div></li><li><span>3</span><div><strong>Save a project</strong><small>Immutable analysis versions make changes traceable.</small></div></li><li><span>4</span><div><strong>Export a backup</strong><small>Keep a portable copy outside browser storage.</small></div></li></ol></section></div></section>`;
}

export function advisor(initial={}){
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">Guided planning</div><h1>Friendly Advisor</h1><p class="muted">Describe the workload in ordinary language. The planner stays deterministic and versioned.</p></div>${pill('Contract 1.13.0','info')}</div><form id="advisor-form" class="wizard panel"><div class="wizard-step"><span>1</span><div><h3>What are you building?</h3><label>Product, data and important behaviors<textarea name="description" minlength="10" maxlength="5000" required placeholder="A customer portal with login, file uploads, analytics, webhooks and background reports…">${esc(initial.description||'')}</textarea></label><div class="chips"><button type="button" data-template="SaaS">SaaS</button><button type="button" data-template="E-commerce">E-commerce</button><button type="button" data-template="API">API</button><button type="button" data-template="Data">Data platform</button><button type="button" data-template="ML">ML inference</button></div></div></div><div class="wizard-step"><span>2</span><div><h3>Scale & constraints</h3><div class="form-grid"><label>Monthly active users<input type="number" name="estimated_users" min="1" max="100000000" value="${initial.estimated_users||5000}" required></label><label>Budget profile<select name="budget">${budgetOptions(initial.budget||'medium')}</select></label><label>AWS region<select name="region">${regionOptions(initial.region||'eu-central-1')}</select></label><label class="check"><input type="checkbox" name="advanced_guide" ${initial.advanced_guide===false?'':'checked'}><span>Include advanced operations guide</span></label></div></div></div><div class="wizard-actions"><button class="btn primary large" type="submit">Analyze architecture →</button><span class="hint">Transparent deterministic recommendations, not a probabilistic cost forecast.</span></div></form><div id="advisor-result"></div></section>`;
}

export function analysisResult(result,{showPersist=true}={}){
  if(!result)return '';
  const a=result.analysis,c=result.cost_analysis,g=result.implementation_guide;
  const services=(result.services||[]).map(s=>{const market=String((result.marketplace_links||{})[s.id]||'');const marketLink=market.startsWith('https://aws.amazon.com/marketplace/')?`<a class="hint" href="${esc(market)}" target="_blank" rel="noopener noreferrer">AWS Marketplace ↗</a>`:'';return `<article class="service"><div class="service-icon">AWS</div><div><strong>${esc(s.name)}</strong><small>${esc(s.category)}</small><p>${esc(s.why_needed)}</p>${marketLink}</div><span class="price">${esc(s.typical_monthly)}</span></article>`}).join('');
  const phases=(g?.phases||[]).map((p,i)=>`<article><span>${i+1}</span><h3>${esc(p.name)}</h3><small>${esc(p.duration)}</small><ul>${(p.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article>`).join('');
  const breakdown=Object.values(c.breakdown||{}),max=Math.max(1,...breakdown.map(x=>Number(x.maximum||0))),chart=breakdown.map(x=>`<div class="chart-row"><span>${esc(x.name)}</span><div><i style="width:${Math.max(2,Math.round(Number(x.maximum||0)/max*100))}%"></i></div><b>$${Number(x.maximum||0).toFixed(0)}</b></div>`).join('');
  const scenarios=(result.scenarios||[]).map(x=>`<article class="scenario-card ${esc(x.name)}"><div class="eyebrow">${esc(x.name)}</div><h3>${esc(x.title)}</h3><strong>$${Number(x.monthly_planning_cost||0).toFixed(2)} / mo</strong><p>${esc(x.availability_target)}</p><ul>${(x.rationale||[]).map(y=>`<li>${esc(y)}</li>`).join('')}</ul></article>`).join('');
  const risks=(result.architecture_risks||[]).map(r=>`<article class="optimization"><span class="pill ${r.severity==='high'?'danger':r.severity==='medium'?'draft':'info'}">${esc(r.severity)}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.recommendation)}</p></div></article>`).join('');
  const pillars=(result.well_architected||[]).map(x=>`<article class="scenario-card"><div class="eyebrow">${esc(x.status)}</div><h3>${esc(x.pillar)}</h3><p>${esc(x.note)}</p></article>`).join('');
  const badges=(result.badges||[]).map(b=>`<div class="badge ${b.earned?'earned':''}"><strong>${esc(b.name)}</strong><small>${esc(b.description)}</small></div>`).join('');
  const opts=(result.optimization_suggestions||[]).map(o=>`<article class="optimization"><span class="pill ${esc(o.impact)}">${esc(o.impact)}</span><div><strong>${esc(o.title)}</strong><p>${esc(o.recommendation)}</p></div>${o.estimated_savings_percent!=null?`<b>~${Number(o.estimated_savings_percent).toFixed(0)}%</b>`:''}</article>`).join('');
  const adrs=(result.architecture_decisions||[]).map(d=>`<details><summary>${esc(d.id)} · ${esc(d.title)}</summary><p>${esc(d.decision)}</p><p class="hint"><strong>Alternatives:</strong> ${(d.alternatives||[]).map(esc).join(', ')}</p></details>`).join('');
  return `<section class="result-stack"><div class="result-hero panel"><div><div class="eyebrow">Recommended baseline · ${esc(a.classifier||'')}</div><h2>${esc(a.project_type)}</h2><p>Confidence <strong>${Math.round(a.confidence*100)}%</strong> · ${(a.detected_features||[]).length} detected features · ${esc(a.knowledge_version||'')}</p></div><div class="cost-badge"><small>Typical monthly planning</small><strong>${esc(c.summary.typical)}</strong><span>${esc(c.summary.minimum)} – ${esc(c.summary.maximum)}</span></div></div>${risks?`<section class="panel"><div class="panel-head"><h2>Architecture risks</h2><span>Explainable rule findings</span></div><div class="optimization-list">${risks}</div></section>`:'<section class="security-note"><strong>No high-signal rule fired</strong><p>This is not a security certification; validate service limits, threat model and recovery objectives before deployment.</p></section>'}${pillars?`<section class="panel"><div class="panel-head"><h2>Well-Architected review</h2><span>Six pillars</span></div><div class="scenario-grid">${pillars}</div></section>`:''}${scenarios?`<section class="panel"><div class="panel-head"><div><div class="eyebrow">Architecture choices</div><h2>Essential · Balanced · Resilient</h2></div><span>Immutable scenario basis</span></div><div class="scenario-grid">${scenarios}</div></section>`:''}<div class="result-grid"><section class="panel"><h2>Recommended services</h2><div class="service-list">${services}</div></section><section class="panel"><h2>Cost envelope</h2><div class="cost-three"><div><small>Minimum</small><strong>${esc(c.summary.minimum)}</strong></div><div><small>Typical</small><strong>${esc(c.summary.typical)}</strong></div><div><small>Maximum</small><strong>${esc(c.summary.maximum)}</strong></div></div><div class="cost-chart">${chart}</div><ul class="compact">${(c.assumptions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section></div>${badges?`<section class="panel"><div class="panel-head"><h2>Badges & learning feedback</h2><span>Derived, not security state</span></div><div class="badge-row">${badges}</div></section>`:''}${opts?`<section class="panel"><h2>Optimization suggestions</h2><div class="optimization-list">${opts}</div></section>`:''}<section class="panel"><div class="panel-head"><div><div class="eyebrow">Implementation</div><h2>${esc(g?.introduction?.title||'Implementation guide')}</h2></div><span>${esc(g?.introduction?.estimated_effort||'')}</span></div><p class="muted">${esc(g?.introduction?.overview||'')}</p><div class="phase-grid">${phases}</div>${adrs?`<div class="adr-list"><h3>Architecture Decision Records</h3>${adrs}</div>`:''}</section><div class="action-strip">${showPersist?'<button class="btn primary" data-action="save-analysis-project">Save as project</button>':''}<button class="btn" data-action="generate-iac">Generate Terraform</button><button class="btn" data-action="generate-report">Generate report</button><button class="btn" data-action="compare-regions">Compare regions</button><button class="btn ghost" data-action="print">Print</button></div><div id="generated-output"></div></section>`;
}

export function projectsPage(projects=[],nextCursor=null){
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">Durable workspace</div><h1>Projects</h1><p class="muted">Versioned specifications with immutable analysis history.</p></div><button class="btn primary" data-action="show-project-form">+ New project</button></div><div id="project-create-slot"></div><section class="panel">${projects.length?`<div class="project-table"><div class="thead"><span>Project</span><span>Region</span><span>Users</span><span>Status</span><span>Revision</span></div>${projects.map(p=>`<a href="#/project/${encodeURIComponent(p.id)}"><span><strong>${esc(p.name)}</strong><small>${esc(p.description).slice(0,90)}</small></span><span>${esc(p.region)}</span><span>${num(p.estimated_users)}</span><span>${pill(p.status,p.status)}</span><span>r${p.revision}</span></a>`).join('')}</div>`:'<div class="empty"><h3>No projects in this tenant</h3><p>Create your first durable project.</p></div>'}${nextCursor?`<div class="form-actions"><a class="btn" href="#/projects?cursor=${encodeURIComponent(nextCursor)}">Next page →</a></div>`:''}</section></section>`;
}

export function projectCreateForm(initial={}){
  return `<form id="project-create-form" class="panel inline-form"><div class="panel-head"><h2>New project</h2><button type="button" class="icon-btn" data-action="hide-project-form">×</button></div><div class="form-grid"><label>Project name<input name="name" required minlength="2" maxlength="120" value="${esc(initial.name||'')}"></label><label>Status<select name="status"><option>draft</option><option>active</option></select></label><label class="span2">Description<textarea name="description" required minlength="10" maxlength="5000">${esc(initial.description||'')}</textarea></label><label>Monthly active users<input name="estimated_users" type="number" min="1" max="100000000" value="${initial.estimated_users||5000}"></label><label>Budget<select name="budget">${budgetOptions(initial.budget||'medium')}</select></label><label>Region<select name="region">${regionOptions(initial.region||'eu-central-1')}</select></label></div><button class="btn primary" type="submit">Create project</button></form>`;
}

export function projectDetail(p,analyses=[],nextCursor=null){
  const history=analyses.length?`<div class="history">${analyses.map(a=>`<button data-action="open-analysis" data-version="${a.version}"><span>v${a.version}</span><div><strong>${esc(a.project_type)}</strong><small>${formatDate(a.created_at)}</small></div><b>${esc(a.typical_monthly_cost)}</b></button>`).join('')}</div>`:'<div class="empty small"><p>No persisted analyses yet.</p></div>';
  return `<section class="page"><div class="page-head"><div><a class="back" href="#/projects">← Projects</a><div class="eyebrow">${esc(p.id)}</div><h1>${esc(p.name)}</h1><p class="muted">Revision ${p.revision} · updated ${formatDate(p.updated_at)}</p></div>${pill(p.status,p.status)}</div><div class="detail-grid"><section class="panel"><h2>Project specification</h2><form id="project-edit-form"><input type="hidden" name="expected_revision" value="${p.revision}"><label>Name<input name="name" required minlength="2" maxlength="120" value="${esc(p.name)}"></label><label>Description<textarea name="description" required minlength="10" maxlength="5000">${esc(p.description)}</textarea></label><div class="form-grid"><label>Users<input type="number" name="estimated_users" min="1" max="100000000" value="${p.estimated_users}"></label><label>Budget<select name="budget">${budgetOptions(p.budget)}</select></label><label>Region<select name="region">${regionOptions(p.region)}</select></label><label>Status<select name="status">${['draft','active','archived'].map(x=>`<option ${x===p.status?'selected':''}>${x}</option>`).join('')}</select></label></div><button class="btn" type="submit">Save changes</button></form></section><section class="panel"><h2>Analysis actions</h2><p class="muted">Each persisted run is immutable and receives the next sequential version.</p><button class="btn primary block" data-action="run-project-analysis" ${p.status==='archived'?'disabled':''}>✦ Run & persist new analysis</button><button class="btn block" data-action="project-iac">Generate Terraform</button><button class="btn block" data-action="project-report">Generate report</button>${analyses.length?`<a class="btn block" href="#/finops?project=${encodeURIComponent(p.id)}&version=${analyses[0].version}">Open FinOps workspace</a>`:''}${p.status==='archived'?'<p class="warning">Archived projects cannot receive new analysis versions.</p>':''}<div id="project-output"></div></section></div><section class="panel"><div class="panel-head"><h2>Immutable analysis history</h2><span>${analyses.length} shown</span></div>${history}${nextCursor?`<div class="form-actions"><a class="btn" href="#/project/${encodeURIComponent(p.id)}?analysis_cursor=${encodeURIComponent(nextCursor)}">Next history page →</a></div>`:''}${analyses.length?`<div class="form-actions"><select id="report-bundle-version">${analyses.map(a=>`<option value="${a.version}">v${a.version}</option>`).join('')}</select><button class="btn" data-action="export-report-bundle">Export provenance report ZIP</button></div>`:''}</section><div id="analysis-version-slot"></div></section>`;
}

export function teamPage(members=[],nextCursor=null,settings=null){
  const standalone=settings?.authMode==='standalone';
  const rows=members.length?`<div class="members">${members.map(m=>`<article><div class="avatar">${esc(m.subject.slice(0,2).toUpperCase())}</div><div><strong>${esc(m.subject)}</strong><small>${esc(m.status)} · revision ${m.revision}${m.local_only?' · local':''}</small></div>${pill(m.role,'info')}${m.role!=='owner'?`<button class="icon-btn" data-action="edit-member" data-subject="${esc(m.subject)}" data-role="${esc(m.role)}" data-status="${esc(m.status)}" data-revision="${m.revision}">✎</button>`:''}</article>`).join('')}</div>`:'<p class="muted">No memberships returned.</p>';
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">${standalone?'Local personas':'Tenant administration'}</div><h1>Team</h1><p class="muted">${standalone?'Standalone roles are organizational labels for planning and do not protect data from someone who controls this browser profile. Use the AWS connector/backend for enforceable multi-user authorization.':'Viewer, editor and admin memberships are enforced by the backend.'}</p></div></div>${standalone?'<section class="warning">Local roles are not a security boundary.</section>':''}<div class="two-col"><section class="panel"><h2>Members</h2>${rows}</section><form class="panel" id="member-create-form"><h2>${standalone?'Add local persona':'Add member'}</h2><label>${standalone?'Persona label':'Cognito subject'}<input name="subject" required maxlength="256" placeholder="${standalone?'architect@example':'user subject / UUID'}"></label><label>Role<select name="role"><option>viewer</option><option>editor</option><option>admin</option></select></label><button class="btn primary" type="submit">${standalone?'Add persona':'Grant membership'}</button><p class="hint">${standalone?'Useful for role modelling and report ownership; not authentication.':'The backend applies role ceilings and tenant authorization.'}</p></form></div>${nextCursor?`<div class="form-actions"><a class="btn" href="#/team?cursor=${encodeURIComponent(nextCursor)}">Next member page →</a></div>`:''}<div id="member-edit-slot"></div></section>`;
}

export function memberEditForm(m){
  return `<form class="panel inline-form" id="member-edit-form"><h2>Edit ${esc(m.subject)}</h2><input type="hidden" name="subject" value="${esc(m.subject)}"><input type="hidden" name="expected_revision" value="${m.revision}"><div class="form-grid"><label>Role<select name="role">${['viewer','editor','admin'].map(x=>`<option ${x===m.role?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select name="status"><option ${m.status==='active'?'selected':''}>active</option><option ${m.status==='suspended'?'selected':''}>suspended</option></select></label></div><button class="btn" type="submit">Apply change</button></form>`;
}

export function auditPage(events=[],nextCursor=null,settings=null){
  const standalone=settings?.authMode==='standalone';
  const rows=events.length?`<div class="audit-list">${events.map(e=>`<article><span class="audit-dot"></span><div><strong>${esc(e.action)}</strong><small>${esc(e.resource_type)} · ${esc(e.resource_id)}</small><p>${formatDate(e.occurred_at)} · actor ${esc(e.actor_subject)}</p></div><code>${esc(e.request_id)}</code></article>`).join('')}</div>`:'<div class="empty"><p>No audit events returned.</p></div>';
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">Governance</div><h1>${standalone?'Local activity log':'Audit trail'}</h1><p class="muted">${standalone?'This log improves traceability inside the local workspace, but someone controlling this browser can alter local state. Exported backup checksums provide integrity checking, not a tamper-proof ledger.':'Actor, action, resource and request ID for server-authorized tenant mutations.'}</p></div></div>${standalone?'<section class="warning">Local activity is not AWS CloudTrail and is not an independent security record.</section>':''}<section class="panel">${rows}${nextCursor?`<div class="form-actions"><a class="btn" href="#/audit?cursor=${encodeURIComponent(nextCursor)}">Next audit page →</a></div>`:''}</section></section>`;
}

export function settingsPage(s){
  return `<section class="page narrow"><div class="eyebrow">Runtime connection</div><h1>Settings</h1><p class="muted">Standalone is the default: no backend, account or cloud is required. AWS/Cognito is an optional connector for live cloud evidence.</p><form id="settings-form" class="panel settings-form"><label>Authentication mode<select name="authMode"><option value="standalone" ${s.authMode==='standalone'?'selected':''}>Standalone — full local-first application</option><option value="demo" ${s.authMode==='demo'?'selected':''}>Demo — disposable browser simulation</option><option value="cognito" ${s.authMode==='cognito'?'selected':''}>AWS connector — Cognito + API</option><option value="local" ${s.authMode==='local'?'selected':''}>Local debug — local/test backend only</option></select></label><label>API base URL<input name="apiBaseUrl" type="url" placeholder="https://abc.execute-api.eu-central-1.amazonaws.com/staging" value="${esc(s.apiBaseUrl)}"></label><div class="settings-group"><h3>Cognito / PKCE</h3><label>Cognito domain<input name="cognitoDomain" type="url" placeholder="https://your-domain.auth.eu-central-1.amazoncognito.com" value="${esc(s.cognitoDomain)}"></label><label>Public app client ID<input name="cognitoClientId" value="${esc(s.cognitoClientId)}"></label><label>Scopes<input name="cognitoScopes" value="${esc(s.cognitoScopes)}"></label><label>Redirect URI<input name="redirectUri" value="${esc(s.redirectUri)}"></label><label>Logout URI<input name="logoutUri" value="${esc(s.logoutUri)}"></label></div><div class="settings-group"><h3>Workspace</h3><label>Tenant ID<input name="tenantId" value="${esc(s.tenantId)}" placeholder="tenant_…"></label></div><div class="settings-group"><h3>Local debug identity</h3><label>Subject<input name="localSubject" value="${esc(s.localSubject)}"></label><label>Username<input name="localUsername" value="${esc(s.localUsername)}"></label></div><div class="form-actions"><button class="btn primary" type="submit">Save settings</button><button class="btn ghost" type="button" data-action="test-connection">Test runtime</button><button class="btn danger ghost" type="button" data-action="reset-settings">Reset</button></div></form><section class="security-note"><strong>Security boundary</strong><p>Standalone mode stores application data locally and makes no backend requests. The optional AWS connector uses Cognito Authorization Code + PKCE; AWS credentials and client secrets must never be placed in this frontend.</p></section></section>`;
}

export function aboutPage(s){
  return `<section class="page narrow"><div class="eyebrow">Release information</div><h1>AWS Friendly Counsellor Web</h1><section class="panel"><dl class="facts"><div><dt>Web milestone</dt><dd>${esc(s.webVersion)}</dd></div><div><dt>Application</dt><dd>3.20.0-m5a1 · read-only discovery</dd></div><div><dt>API contract</dt><dd>1.13.0</dd></div><div><dt>Hosting target</dt><dd>GitHub Pages / any static host</dd></div></dl><h2>What is local</h2><p>Advisor, expanded knowledge engine, projects, immutable analyses, planning roles, audit, FinOps, streaming CSV/NDJSON cost import, Terraform, reports, encrypted backups, recovery checkpoints and imported AWS read-only inventory can run without a backend.</p><h2>What still needs a trust boundary</h2><p>Enforceable multi-user authorization, automatic cross-device synchronization and claims about live Cost Explorer, CloudTrail, WAF, Cognito, CodeDeploy or PITR require an optional remote connector. The standalone app never labels local equivalents as AWS-live evidence.</p></section></section>`;
}

export function regionComparison(result){return `<section class="panel generated"><div class="panel-head"><h2>Regional simulation</h2><span>Same explicit usage</span></div><div class="scenario-grid">${(result.simulations||[]).map(x=>`<article class="scenario-card"><div class="eyebrow">${esc(x.source_state)}</div><h3>${esc(x.region)}</h3><strong>$${Number(x.total_monthly).toFixed(2)} / mo</strong></article>`).join('')}</div></section>`;}

export function finopsPage({projects=[],selectedProject=null,analyses=[],workspace=null,pricingStatus=null,estimates=[],actuals=[],settings=null}){
  const standalone=settings?.authMode==='standalone';
  const projectOptions=projects.map(p=>`<option value="${esc(p.id)}" ${selectedProject?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');
  const selectedVersion=workspace?.version||analyses[0]?.version||'';
  const versions=analyses.map(a=>`<option value="${a.version}" ${Number(selectedVersion)===Number(a.version)?'selected':''}>v${a.version} · ${esc(a.project_type)} · ${esc(a.typical_monthly_cost)}</option>`).join('');
  const result=workspace?.result_payload||workspace?.result||{};
  const usage=result.usage_profile||{};
  const serviceIds=(result.services||[]).map(x=>x.id).filter(Boolean);
  const usageJson=esc(JSON.stringify(usage,null,2));
  const servicesCsv=esc(serviceIds.join(','));
  const estimateRows=estimates.map(e=>`<article class="finops-row"><div><strong>${esc(e.rate_type)}</strong><small>${esc(e.account_id)} · workspace v${e.workspace_version} · revision ${e.revision}</small></div><span>${esc(e.status)}</span><b>${e.account_monthly==null?'—':`$${Number(e.account_monthly).toFixed(2)}`}</b><em>${esc(e.reconciliation)}</em><div class="form-actions"><button class="btn mini" data-action="estimate-refresh" data-id="${esc(e.estimate_id)}">Refresh</button><button class="btn mini ghost" data-action="estimate-extend" data-id="${esc(e.estimate_id)}" data-revision="${e.revision}">Extend</button><button class="btn mini ghost" data-action="estimate-revisions" data-id="${esc(e.estimate_id)}">Revisions</button></div></article>`).join('');
  const actualRows=actuals.map(x=>`<article class="finops-row"><div><strong>${esc(x.source)}</strong><small>${esc(x.start_date)} → ${esc(x.end_date)} · ${esc(x.status||'final')} · revision ${x.revision}</small><small>captured ${esc(x.captured_at||'—')} · ${x.source==='local_manual'||x.source==='cur_2_0_import'?'local/imported evidence':`${Number(x.api_request_count||0)} AWS API requests · query cost $${Number(x.query_cost_usd||0).toFixed(2)}`}</small></div><span>${esc(x.drift_state)}</span><b>$${Number(x.actual_total).toFixed(2)}</b><em class="${esc(x.severity)}">${esc(x.severity)}</em><div class="form-actions">${(x.source==='cost_explorer'||x.source==='local_manual')?`<button class="btn mini" data-action="actual-refresh" data-id="${esc(x.snapshot_id)}">Refresh</button>`:''}<button class="btn mini ghost" data-action="actual-revisions" data-id="${esc(x.snapshot_id)}">Revisions</button></div></article>`).join('');
  const workspacePanel=workspace?`<div class="two-col"><form class="panel" id="usage-pricing-form"><h2>Explicit usage pricing</h2><label>Workspace<select id="finops-version">${versions}</select></label><label>Region<select name="region">${regionOptions(selectedProject?.region||'eu-central-1')}</select></label><label>Service IDs <small>comma separated</small><input name="service_ids" value="${servicesCsv}"></label><label>Usage quantities JSON<textarea name="usage_json" required>${usageJson}</textarea></label><label>Transfer paths JSON<textarea name="transfer_paths_json">[]</textarea></label>${standalone?'<p class="hint">Authoritative live Price List mode requires the optional AWS connector.</p>':'<label class="check"><input type="checkbox" name="strict_authoritative"><span>Require all lines from authoritative Price List</span></label>'}<button class="btn primary" type="submit">Price explicit usage</button><div id="pricing-preview"></div></form><form class="panel" id="region-simulation-form"><h2>Regional comparison</h2><label>Regions <small>comma separated, max 8</small><input name="regions" value="us-east-1,eu-west-1,eu-central-1,ap-southeast-1"></label><input type="hidden" name="service_ids" value="${servicesCsv}"><textarea name="usage_json" hidden>${usageJson}</textarea><button class="btn" type="submit">Compare identical usage</button><div id="region-preview"></div><h3>Workspace provenance</h3><p class="hint">Pricing uses explicit quantities stored with immutable analysis v${workspace.version}. Public quote lines report source, SKU/rate code where available, acquisition time and fallback reason.</p></form></div>`:'';
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">M3-R reconciled FinOps</div><h1>Pricing & actual cost</h1><p class="muted">Explicit quantity planning, embedded or live Price List provenance, local or account-aware estimates, actual-cost/CUR snapshots and forecast-vs-actual drift.</p></div>${pricingStatus?`<span class="pill ${pricingStatus.freshness_state==='fresh'||pricingStatus.source_state==='authoritative'?'active':pricingStatus.freshness_state==='aging'?'draft':'archived'}">${esc(pricingStatus.source_state)} · ${esc(pricingStatus.freshness_state||'')}</span>`:''}</div><section class="panel"><label>Project<select id="finops-project"><option value="">Choose a project</option>${projectOptions}</select></label>${selectedProject?`<div class="facts"><div><dt>Project</dt><dd>${esc(selectedProject.name)}</dd></div><div><dt>Region</dt><dd>${esc(selectedProject.region)}</dd></div></div>`:'<p class="muted">Choose a project to work with its immutable analysis workspaces.</p>'}</section>${selectedProject?`${workspacePanel}<div class="two-col"><section class="panel"><h2>Quick public-pricing check</h2><label>Workspace<select id="finops-version">${versions}</select></label><button class="btn" data-action="preview-public-pricing" ${analyses.length?'':'disabled'}>Price stored usage</button><p class="hint">For edits and transfer paths use the explicit-usage form above. Standalone uses the embedded snapshot; connector mode can use live pricing.</p></section><form class="panel" id="account-estimate-form"><h2>${standalone?'Local equivalent estimate':'Account-aware estimate'}</h2><label>Workspace<select name="version">${versions}</select></label>${standalone?'<input type="hidden" name="account_id" value="000000000000">':'<label>AWS account ID<input name="account_id" pattern="[0-9]{12}" maxlength="12" required placeholder="123456789012"></label>'}${standalone?'<input type="hidden" name="rate_type" value="BEFORE_DISCOUNTS"><p class="hint">Private/account discounts are not simulated locally. Connect AWS for real account-aware rates.</p>':'<label>Rate type<select name="rate_type"><option>BEFORE_DISCOUNTS</option><option>AFTER_DISCOUNTS</option><option>AFTER_DISCOUNTS_AND_COMMITMENTS</option></select></label>'}<label>TTL days<input name="ttl_days" type="number" min="1" max="365" value="30"></label><button class="btn" type="submit">${standalone?'Create local estimate':'Create Pricing Calculator estimate'}</button><p class="hint">${standalone?'Computed locally from the embedded rate snapshot; no AWS account call is made.':'Fails closed unless the connector feature flag and AWS-account allowlist permit it.'}</p></form></div><section class="panel"><div class="panel-head"><h2>${standalone?'Local estimate history':'Pricing Calculator estimates'}</h2><span>${estimates.length} shown</span></div>${estimateRows||`<p class="muted">${standalone?'No local planning estimates.':'No persisted account-aware estimates.'}</p>`}</section><div class="two-col"><form class="panel" id="actual-cost-form"><h2>${standalone?'Manual actual-cost snapshot':'Cost Explorer snapshot'}</h2><label>Estimate<select name="estimate_id">${estimates.map(e=>`<option value="${esc(e.estimate_id)}">${esc(e.account_id)} · ${esc(e.rate_type)}</option>`).join('')}</select></label>${standalone?'<input type="hidden" name="account_id" value="000000000000">':'<label>AWS account ID<input name="account_id" pattern="[0-9]{12}" maxlength="12" required></label>'}<div class="form-grid"><label>Start<input name="start_date" type="date" required></label><label>End <small>exclusive</small><input name="end_date" type="date" required></label></div>${standalone?'<label>Actual total (USD)<input name="actual_total" type="number" min="0" step="0.000001" required></label>':''}<label>Metric<select name="metric"><option>UnblendedCost</option><option>AmortizedCost</option><option>NetAmortizedCost</option></select></label><button class="btn" type="submit">${standalone?'Persist actual cost':'Collect actual cost'}</button></form><form class="panel" id="cur-import-form"><h2>CUR 2.0 aggregate import</h2><label>Estimate<select name="estimate_id">${estimates.map(e=>`<option value="${esc(e.estimate_id)}">${esc(e.account_id)} · ${esc(e.rate_type)}</option>`).join('')}</select></label>${standalone?'<input type="hidden" name="account_id" value="000000000000">':'<label>AWS account ID<input name="account_id" pattern="[0-9]{12}" maxlength="12" required></label>'}<div class="form-grid"><label>Start<input name="start_date" type="date" required></label><label>End<input name="end_date" type="date" required></label></div><label>CUR/actual-cost file <small>CSV/NDJSON (including .gz) stream incrementally; JSON arrays up to 100 MB</small><input type="file" name="cur_file" accept=".csv,.json,.jsonl,.ndjson,.gz,text/csv,application/json,application/gzip"></label><label>Or paste aggregated JSON rows<textarea name="rows" placeholder='[{"date":"2026-01-01","service":"AWS Lambda","amount":12.34,"currency":"USD","estimated":false}]'></textarea></label><div id="cur-progress" class="hint"></div><button class="btn" type="submit">Import CUR / actual cost</button></form></div><section class="panel"><div class="panel-head"><h2>Actual vs forecast</h2><span>${actuals.length} snapshots</span></div>${actualRows||'<p class="muted">No actual-cost snapshots.</p>'}</section>`:''}<div id="finops-output"></div></section>`;
}

export function revisionPanel(title,rows=[]){return `<section class="panel generated"><div class="panel-head"><h2>${esc(title)}</h2><span>${rows.length} immutable revisions</span></div><div class="history">${rows.map(r=>`<article class="finops-row"><div><strong>Revision ${r.revision}</strong><small>${esc(r.updated_at||r.created_at||'')}</small></div><span>${esc(r.status||r.drift_state||'')}</span><code>${esc(JSON.stringify(r))}</code></article>`).join('')}</div></section>`;}

export function pricingPreview(q){const max=Math.max(1,...(q.lines||[]).map(x=>Number(x.partial_cost||0)));return `<div class="generated"><div class="facts"><div><dt>Monthly total</dt><dd>$${Number(q.total_monthly).toFixed(2)}</dd></div><div><dt>Source state</dt><dd>${esc(q.source_state)}</dd></div></div><div class="cost-chart">${(q.lines||[]).filter(x=>Number(x.partial_cost)>0).map(x=>`<div class="chart-row"><span>${esc(x.service_id)} · ${esc(x.dimension)}</span><div><i style="width:${Math.max(2,Math.round(Number(x.partial_cost)/max*100))}%"></i></div><b>$${Number(x.partial_cost).toFixed(2)}</b></div>`).join('')}</div><p class="hint">${(q.assumptions||[]).map(esc).join(' · ')}</p></div>`;}

export function privacyPage(settings=null){const standalone=settings?.authMode==='standalone';return `<section class="page narrow"><div class="eyebrow">GDPR / privacy</div><h1>My data</h1><p class="muted">Export personal data or erase the local vault. Exported backup files are outside the application and must be deleted separately if you want complete local erasure.</p><div class="two-col"><section class="panel"><h2>Data access</h2><p>Generate a machine-readable export of the data associated with the active local identity/tenant.</p><button class="btn primary" data-action="privacy-export">Download my data</button></section><section class="panel"><h2>${standalone?'Local erasure':'Deletion request'}</h2><p>${standalone?'Standalone erasure deletes this browser vault after a second confirmation.':'Connector mode creates the server-side erasure workflow and may require identity-provider deletion.'}</p><button class="btn danger" data-action="privacy-delete">${standalone?'Erase local data':'Request erasure'}</button></section></div><div id="privacy-output"></div></section>`;}

export function dataPage(settings,info={},backup={},recovery=[]){const standalone=settings?.authMode==='standalone',usage=info.usage_bytes!=null&&info.quota_bytes?`${Math.round(info.usage_bytes/1024/1024)} MB / ${Math.round(info.quota_bytes/1024/1024)} MB`:'Unknown',backupText=backup.last_backup_at?`${formatDate(backup.last_backup_at)} · ${backup.age_days} day(s) ago`:'Never';return `<section class="page narrow"><div class="eyebrow">Local-first resilience</div><h1>Data, Backup & Recovery</h1><p class="muted">The app is standalone, but browser storage is not the same thing as durable cloud backup. This page makes that boundary explicit and gives you portable, integrity-checked recovery options.</p><div class="stat-grid"><div class="stat"><small>Mode</small><strong>${esc(settings?.authMode||'')}</strong><span>${standalone?'No backend required':'Connector-backed'}</span></div><div class="stat"><small>Storage</small><strong>${esc(info.storage||'—')}</strong><span>${usage}</span></div><div class="stat"><small>Persistence</small><strong>${info.persisted===true?'Granted':info.persisted===false?'Best effort':'Unknown'}</strong><span>Browser eviction protection</span></div><div class="stat"><small>Last backup</small><strong>${backup.last_backup_at?`${backup.age_days}d`:'Never'}</strong><span>${esc(backupText)}</span></div></div>${backup.recommended?'<p class="warning">Backup recommended now. Keep a copy outside this browser profile.</p>':''}<div class="two-col"><section class="panel"><h2>Portable backup</h2><p>Versioned JSON with a SHA-256 integrity checksum. The checksum detects accidental/post-export changes; it is not a digital signature against a malicious editor.</p><button class="btn primary" data-action="backup-export" ${standalone?'':'disabled'}>Download backup</button><button class="btn block" data-action="backup-export-encrypted" ${standalone?'':'disabled'}>Download encrypted backup</button><button class="btn ghost block" data-action="request-persistence" ${standalone?'':'disabled'}>Ask browser to protect storage</button></section><form class="panel" id="backup-import-form"><h2>Restore backup</h2><label>AWSFC backup JSON<input type="file" name="backup" accept="application/json,.json" ${standalone?'required':'disabled'}></label><label>Passphrase <small>only for encrypted backups</small><input type="password" name="passphrase" autocomplete="off" minlength="8"></label><button class="btn" type="submit" ${standalone?'':'disabled'}>Verify & restore</button></form></div><section class="panel"><div class="panel-head"><h2>Automatic local recovery checkpoints</h2><span>${recovery.length} retained</span></div>${recovery.length?`<div class="history">${recovery.slice(0,12).map(r=>`<button data-action="recovery-restore" data-id="${esc(r.id)}"><span>r${r.state_revision}</span><div><strong>${r.project_count} projects</strong><small>${formatDate(r.created_at)}</small></div><b>Restore</b></button>`).join('')}</div>`:'<p class="muted">Checkpoints appear automatically before local mutations.</p>'}</section><section class="panel"><h2>Pricing snapshot</h2><p>Import a versioned local JSON catalog. The app reports freshness/expiry rather than presenting an old snapshot as current AWS pricing.</p><form id="pricing-catalog-import-form"><label>Pricing snapshot JSON<input type="file" name="catalog" accept="application/json,.json" ${standalone?'required':'disabled'}></label><button class="btn" type="submit" ${standalone?'':'disabled'}>Import & validate snapshot</button></form><button class="btn ghost block" data-action="pricing-refresh-bundled" ${standalone?'':'disabled'}>Check latest Pages pricing snapshot</button><p class="hint">This optional action performs one same-origin network request. Normal standalone use remains zero-network.</p></section><section class="panel"><h2>Privacy-preserving diagnostics</h2><p>Diagnostics stay local and redact content-like fields. Export them only if you choose to share them.</p><div class="form-actions"><button class="btn" data-action="diagnostics-export">Download diagnostics</button><button class="btn ghost" data-action="diagnostics-clear">Clear diagnostics</button></div></section><section class="panel"><h2>Local reset</h2><p class="warning">Deletes the standalone vault and local recovery checkpoints. Export a backup first if needed.</p><button class="btn danger" data-action="standalone-reset" ${standalone?'':'disabled'}>Delete local vault</button></section>${standalone?'':'<section class="security-note"><strong>Connector mode</strong><p>Local backup/restore manages only the standalone vault. Remote connector data remains governed by its backend.</p></section>'}</section>`;}

export function discoveryPage(data=null,settings=null){
  const d=data?.discovery||null,s=data?.summary||d?.summary||null;
  const services=s?.services||[],regions=s?.regions||[],resources=d?.resources||[],errors=d?.errors||[];
  const serviceRows=services.length?services.map(([name,count])=>`<article class="finops-row"><div><strong>${esc(name)}</strong><small>Discovered resource metadata</small></div><b>${num(count)}</b></article>`).join(''):'<p class="muted">No imported inventory yet.</p>';
  const resourceRows=resources.slice(0,100).map(r=>`<article class="finops-row"><div><strong>${esc(r.name||r.id)}</strong><small>${esc(r.service)} · ${esc(r.type)} · ${esc(r.region)}</small></div><span>${esc(r.state||'—')}</span><b>${esc(String(r.id).slice(0,40))}</b></article>`).join('');
  return `<section class="page"><div class="page-head"><div><div class="eyebrow">M5-A1 · AWS Reality Bridge</div><h1>AWS Discovery</h1><p class="muted">Collect read-only infrastructure metadata with your local AWS CLI, then import the credential-free JSON bundle here. AWS access keys and session tokens never enter this web application.</p></div>${d?pill('Inventory loaded','active'):pill('No inventory','draft')}</div>
  <section class="security-note"><strong>Credential boundary</strong><p>The collector executes on your computer using the AWS CLI credential chain you already configured. The bundle contains account/resource metadata only. Import validation rejects credential-like fields and key material. This milestone does not call AWS directly from GitHub Pages.</p></section>
  <div class="two-col"><section class="panel"><h2>1 · Download the collector</h2><p>Run the collector locally with an AWS identity that has only the read permissions you intend to grant.</p><div class="form-actions"><a class="btn primary" href="./tools/awsfc-discover.py" download>Download collector</a></div><pre><code>python awsfc-discover.py --profile my-readonly-profile --regions eu-central-1,eu-west-1 --output awsfc-discovery.json</code></pre><p class="hint">If --regions is omitted, the collector asks EC2 for enabled regions. Permission failures are recorded as non-fatal coverage gaps rather than hidden.</p></section>
  <form class="panel" id="discovery-import-form"><h2>2 · Import discovery bundle</h2><label>Discovery JSON<input type="file" name="discovery" accept="application/json,.json" required></label><button class="btn primary" type="submit">Validate & import</button><p class="hint">Maximum accepted file size in the browser: 25 MB. Up to 100,000 resources are normalized and deduplicated.</p></form></div>
  ${d?`<div class="stat-grid"><div class="stat"><small>AWS account</small><strong>${esc(d.account?.id||'—')}</strong><span>${esc(d.account?.partition||'aws')}</span></div><div class="stat"><small>Resources</small><strong>${num(s?.resource_count||0)}</strong><span>${num(s?.service_count||0)} services</span></div><div class="stat"><small>Regions</small><strong>${num(s?.region_count||0)}</strong><span>${regions.slice(0,3).map(x=>esc(x[0])).join(', ')||'global only'}</span></div><div class="stat"><small>Coverage gaps</small><strong>${num(s?.error_count||0)}</strong><span>permission/API errors retained</span></div></div>
  <div class="two-col"><section class="panel"><div class="panel-head"><h2>Service inventory</h2><span>${esc(d.collector_version||'collector')}</span></div>${serviceRows}</section><section class="panel"><h2>Evidence metadata</h2><dl class="facts"><div><dt>Generated</dt><dd>${formatDate(d.generated_at)}</dd></div><div><dt>Imported</dt><dd>${formatDate(d.imported_at)}</dd></div><div><dt>Source</dt><dd>${esc(d.source||'local-readonly-collector')}</dd></div><div><dt>Mode</dt><dd>${esc(settings?.authMode||'standalone')}</dd></div></dl><div class="form-actions"><button class="btn" data-action="discovery-export">Export inventory</button><button class="btn danger ghost" data-action="discovery-clear">Clear inventory</button></div></section></div>
  <section class="panel"><div class="panel-head"><h2>Resources</h2><span>showing ${Math.min(100,resources.length)} / ${resources.length}</span></div>${resourceRows||'<p class="muted">No resources returned by the collector.</p>'}</section>
  ${errors.length?`<section class="panel"><div class="panel-head"><h2>Coverage gaps</h2><span>${errors.length} recorded</span></div><div class="audit-list">${errors.slice(0,100).map(e=>`<article><span class="audit-dot"></span><div><strong>${esc(e.scope)}</strong><p>${esc(e.message)}</p></div></article>`).join('')}</div></section>`:''}`:'<section class="panel"><h2>No account evidence imported</h2><p class="muted">Download the collector, run it with a read-only AWS CLI profile, and import the resulting JSON. The app remains fully useful without AWS discovery evidence.</p></section>'}</section>`;
}

export function errorCard(title,message){return `<div class="panel error-card"><strong>${esc(title)}</strong><p>${esc(message)}</p></div>`;}
